(function($) {

    var modal_visible = false;
    var modal_submitting = false;

    // Set the value of the choose shelter form and submit it
    $('.catspride-NominateShelter-wrapper').on('click', '.catspride-NominateShelter-button', function() {

        var shelter_id       = $(this).data('shelter_id');
        var shelter_name     = $(this).data('shelter_name');
        var shelter_location = $(this).data('shelter_location');
        var shelter_zip_code = $(this).parents('.catspride-NominateShelter-single').first().find('input[name="zip_code"]');

        // Populate the modal with the proper shelter information
        $('.cp-chosen-shelter-name').text( shelter_name );
        $('.cp-chosen-shelter-location').text( shelter_location );

        // Populate the form
        $('#input-choose-shelter-favorite_shelter').val( shelter_id );
        if ( shelter_zip_code && shelter_zip_code.length > 0 ) {
            $('#input-choose-shelter-zip_code').val( shelter_zip_code.val() );
        }

        $('.cp-modal-wrapper').show();
        modal_visible = true;

    });

    // Display the bonus code input
    $('.cp-modal-wrapper').on('click', '.cp-bonus-code-prompt', function( e ) {
       e.preventDefault();
       $(this).parents('.cp-modal-wrapper').first().find('.cp-bonus-code-on, .cp-bonus-code-off').toggle();
    });

    // Handle the nomination submission with or without the bonus code
    $('.cp-modal-wrapper').on('click', '.cp-modal-submit, .cp-continue-without-bonus-code', function( e ) {

        e.preventDefault();

        $('.cp-modal-message').hide();

        var bonus_code = '';

        if ( $(this).hasClass( 'cp-modal-submit' ) && $('.cp-modal-body .cp-bonus-code-input').is(':visible') ) {

            bonus_code = $('.cp-modal-body .cp-bonus-code-input').val();

            if ( bonus_code == '' ) {
                $('.cp-modal-error-message').text('You have to enter a bonus code.').show();
                return;
            }

        }

        if ( modal_submitting === true )
            return;

        modal_submitting = true;

        // Set the value of the bonus code
        $('#input-choose-shelter-bonus_code').val( bonus_code );

        $('.cp-modal-loader').show();
        $('.cp-modal-submit').attr('disabled', true);

        $.ajax({
            url : catspride_params.ajax_url,
            type : 'post',
            data : $('form#catspride-ChooseShelterForm').serialize(),
            success : function( response ) {
                var msg = (response.data && response.data.message) ? response.data.message : 'An unknown error has occurred. Please try again later.';
                if ( response.success === true ) {
                    $('.cp-modal-success-message').html( msg ).show();
                    $('.cp-modal-continue').show();
                    $('.cp-modal-submit').hide();
                    $('.cp-bonus-code-off, .cp-bonus-code-on, .cp-continue-without-bonus-code, .cp-submit').hide();
                } else {
                    $('.cp-modal-error-message').html( msg ).show();
                    $('.cp-modal-body .cp-bonus-code-input').val(null);
                }
                $('.cp-modal-loader').hide();
            },
            error : function( response ) {
                var msg = (response.data && response.data.message) ? response.data.message : 'An unknown error has occurred. Please try again later.';
                $('.cp-modal-error-message').html( msg ).show();
            },
            complete: function() {
                $('.cp-modal-loader').hide();
                $('.cp-modal-submit').attr('disabled', false);
                modal_submitting = false;
            }
        });

    });

    $('.cp-modal-wrapper').on('click', '.cp-modal-continue', function( e ) {
        e.preventDefault();
        window.location.href ='/member-dashboard/';
        return false;
    });

    // Listen for a click outside of the modal container and if the modal is visible, hide it.
    $(document).mouseup(function(e)
    {
        if ( modal_visible === true ) {
            var container = $('.cp-modal-inner-wrapper');
            if (!container.is(e.target) && container.has(e.target).length === 0) {

                // If the continue button is visible, that means they were successful, let's send them to the dashboard
                if ( $('.cp-modal-continue').is(':visible') ) {
                    window.location.href ='/member-dashboard/';
                }

                $('.cp-modal-wrapper').fadeOut();
                modal_visible = false;

                // The user clicked out and they didn't succeed, so let's reset the form incase they submit another
                $('.cp-bonus-code-on, .cp-modal-continue, .cp-modal-loader').hide();
                $('.cp-bonus-code-off, .cp-modal-submit').show();
                if ( $('form#catspride-ChooseShelterForm').length > 0 ){
                    $('form#catspride-ChooseShelterForm')[0].reset();
                }
                $('.cp-modal-body .cp-bonus-code-input').val(null);

            }
        }
    });

})(jQuery);